# =============================================================================
# Diagnostic visualization of candidate robustness
# Script: 04C_visualize_candidate_robustness.R
# =============================================================================

# Purpose
# -------
# Visualize the locked candidate-robustness results generated by Analysis 04B.
# This script performs no clustering, differential expression, signature
# generation, LINCS query, candidate reranking, or inferential analysis.

suppressPackageStartupMessages({
  library(dplyr)
  library(ggplot2)
  library(readr)
  library(scales)
  library(signatureSearch)
  library(tidyr)
})

# Download filename may include percentile_v2; install as the original analysis/04C script.
SCRIPT_BUILD <- "04C_PERCENTILE_V2_20260906"
cat("Visualization script build:", SCRIPT_BUILD, "\n")
ANALYSIS_ID <- "revision_candidate_robustness_visualization_v2"
EXPECTED_LOCK <- paste0(
  "1e3a2b827a1429e406303871d547a9dec",
  "07ee4068078c666df69ca82e5428380"
)

ROBUSTNESS_RDS <-
  "data/processed/revision_candidate_robustness_and_null_summary.rds"
BATCH_INDEX_RDS <- "data/processed/revision_lincs_batch_index.rds"
FIGURE_DIR <- "figures/revision/diagnostic"
RESULT_DIR <- "results/revision"
OUTPUT_RDS <- "data/processed/revision_candidate_robustness_figures.rds"

required_files <- c(ROBUSTNESS_RDS, BATCH_INDEX_RDS)
missing_files <- required_files[!file.exists(required_files)]
if (length(missing_files) > 0L) {
  stop("Missing required input(s): ", paste(missing_files, collapse = ", "))
}

dir.create(FIGURE_DIR, recursive = TRUE, showWarnings = FALSE)
dir.create(RESULT_DIR, recursive = TRUE, showWarnings = FALSE)
dir.create(dirname(OUTPUT_RDS), recursive = TRUE, showWarnings = FALSE)


# -----------------------------------------------------------------------------
# Section 1. Load and validate locked inputs
# -----------------------------------------------------------------------------

robustness <- readRDS(ROBUSTNESS_RDS)
batch_index <- readRDS(BATCH_INDEX_RDS)

if (
  !identical(robustness$manifest_content_sha256, EXPECTED_LOCK) ||
    !identical(batch_index$manifest_content_sha256, EXPECTED_LOCK)
) {
  stop("Input objects do not match the frozen revision signature lock.")
}

if (
  !isTRUE(batch_index$all_locked_queries_complete) ||
    batch_index$full_reference_complete_n != 19L ||
    batch_index$null_complete_n != 100L
) {
  stop("The complete locked LINCS batch is not available.")
}

candidate_summary <- robustness$candidate_summary
observed_thp1 <- robustness$observed_thp1
core_query_ids <- robustness$core_query_ids

if (
  nrow(candidate_summary) != 1376L ||
    length(core_query_ids) != 11L ||
    anyDuplicated(candidate_summary$pert) ||
    anyDuplicated(observed_thp1[c("query_id", "pert")])
) {
  stop("Analysis 04B result structure failed validation.")
}

priority_perts <- candidate_summary |>
  dplyr::filter(tolower(pert_iname) %in% c("rosuvastatin", "roflumilast")) |>
  dplyr::pull(pert)

if (length(priority_perts) != 2L) {
  stop("Rosuvastatin and roflumilast were not uniquely identified.")
}

display_name <- function(pert_iname, pert) {
  ifelse(
    is.na(pert_iname) | pert_iname == "" | pert_iname == "UNIDENTIFIED",
    pert,
    pert_iname
  )
}

theme_revision <- function(base_size = 11) {
  theme_bw(base_size = base_size) +
    theme(
      panel.grid.minor = element_blank(),
      panel.grid.major = element_line(linewidth = 0.25, color = "grey90"),
      plot.title = element_text(face = "bold"),
      plot.subtitle = element_text(color = "grey30"),
      legend.position = "right"
    )
}

save_plot_pair <- function(plot, stem, width, height) {
  png_path <- file.path(FIGURE_DIR, paste0(stem, ".png"))
  pdf_path <- file.path(FIGURE_DIR, paste0(stem, ".pdf"))

  ggsave(
    png_path,
    plot = plot,
    width = width,
    height = height,
    units = "in",
    dpi = 400,
    bg = "white"
  )
  ggsave(
    pdf_path,
    plot = plot,
    width = width,
    height = height,
    units = "in",
    device = grDevices::cairo_pdf,
    bg = "white"
  )

  c(png = png_path, pdf = pdf_path)
}

query_labels <- c(
  PRIMARY_150 = "Primary\n150/150",
  PRIMARY_50 = "Primary\n50/50",
  PRIMARY_100 = "Primary\n100/100",
  PRIMARY_200 = "Primary\n200/200",
  C5_ALLREST_MAX150 = "C5 vs\nall rest",
  C5_MARKERLOW_MAX150 = "C5 vs\nmarker-low",
  MARKER_MAX150 = "Marker-high\nvs low",
  RES03_ALLREST_MAX150 = "Resolution\n0.3",
  RES07_ALLREST_MAX150 = "Resolution\n0.7",
  RES10_ALLREST_MAX150 = "Resolution\n1.0",
  P6_INCLUDED_MARKER_MAX150 = "Patient 6\nincluded"
)

if (!setequal(names(query_labels), core_query_ids)) {
  stop("Core-query labels do not match the locked core query set.")
}


# -----------------------------------------------------------------------------
# Figure 1. Core-query NCS heatmap for objective top 20 candidates
# -----------------------------------------------------------------------------

top20 <- candidate_summary |>
  dplyr::arrange(objective_robustness_rank) |>
  dplyr::slice_head(n = 20L) |>
  dplyr::mutate(
    compound_label = display_name(pert_iname, pert),
    compound_label = make.unique(compound_label)
  )

heatmap_data <- observed_thp1 |>
  dplyr::filter(
    pert %in% top20$pert,
    query_id %in% core_query_ids
  ) |>
  dplyr::left_join(
    top20 |>
      dplyr::select(pert, objective_robustness_rank, compound_label),
    by = "pert"
  ) |>
  dplyr::mutate(
    query_label = factor(
      query_labels[query_id],
      levels = unname(query_labels[core_query_ids])
    ),
    compound_label = factor(
      compound_label,
      levels = rev(top20$compound_label)
    ),
    zero_connectivity = !is.na(NCS) & NCS == 0
  )

if (nrow(heatmap_data) != 20L * 11L) {
  stop("Top-20 heatmap does not contain exactly 220 observations.")
}

p_heatmap <- ggplot(
  heatmap_data,
  aes(x = query_label, y = compound_label, fill = NCS)
) +
  geom_tile(color = "white", linewidth = 0.35) +
  geom_point(
    data = heatmap_data |> dplyr::filter(zero_connectivity),
    shape = 4,
    size = 2.2,
    stroke = 0.8,
    color = "black"
  ) +
  scale_fill_gradient2(
    low = "#2166AC",
    mid = "white",
    high = "#B2182B",
    midpoint = 0,
    limits = c(-2.25, 2.25),
    oob = scales::squish,
    name = "THP1 NCS"
  ) +
  labs(
    x = NULL,
    y = NULL,
    title = "Connectivity robustness of the objective top 20 candidates",
    subtitle = "Negative NCS indicates predicted transcriptional reversal; × denotes NCS = 0"
  ) +
  theme_revision(10) +
  theme(
    axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1),
    axis.text.y = element_text(size = 8.5)
  )

heatmap_paths <- save_plot_pair(
  p_heatmap,
  "candidate_robustness_heatmap_top20",
  width = 10.5,
  height = 8.2
)


# -----------------------------------------------------------------------------
# Figure 2. Priority-candidate trajectories across core definitions
# -----------------------------------------------------------------------------

priority_core <- observed_thp1 |>
  dplyr::filter(
    pert %in% priority_perts,
