# -----------------------------------------------------------------------------
# Figure 5. Primary percentile versus integrated robustness percentile
# -----------------------------------------------------------------------------

rank_scatter <- candidate_summary |>
  dplyr::filter(
    !is.na(primary_percentile_all),
    !is.na(median_percentile_all)
  ) |>
  dplyr::mutate(
    compound = display_name(pert_iname, pert),
    priority = tolower(pert_iname) %in% c("rosuvastatin", "roflumilast")
  )

priority_scatter <- rank_scatter |>
  dplyr::filter(priority)

p_rank_scatter <- ggplot(
  rank_scatter,
  aes(x = primary_percentile_all, y = median_percentile_all)
) +
  geom_abline(
    slope = 1,
    intercept = 0,
    linetype = "dashed",
    linewidth = 0.5,
    color = "grey45"
  ) +
  geom_point(color = "grey65", alpha = 0.55, size = 1.4) +
  geom_point(
    data = priority_scatter,
    aes(color = compound),
    size = 3
  ) +
  geom_text(
    data = priority_scatter,
    aes(label = compound, color = compound),
    hjust = -0.08,
    vjust = -0.45,
    size = 3.5,
    show.legend = FALSE
  ) +
  scale_x_continuous(
    labels = scales::percent_format(accuracy = 1),
    limits = c(0, 1),
    breaks = seq(0, 1, by = 0.2),
    expand = expansion(mult = c(0.01, 0.02))
  ) +
  scale_y_continuous(
    labels = scales::percent_format(accuracy = 1),
    limits = c(0, 1),
    breaks = seq(0, 1, by = 0.2),
    expand = expansion(mult = c(0.01, 0.02))
  ) +
  scale_color_manual(
    values = c(rosuvastatin = "#0072B2", roflumilast = "#D55E00"),
    name = NULL
  ) +
  coord_cartesian(clip = "off") +
  labs(
    x = "PRIMARY_150 percentile among 1,376 THP1 compounds",
    y = "Median percentile across 11 core analyses",
    title = "Primary connectivity versus integrated robustness",
    subtitle = paste(
      "Lower percentiles indicate stronger predicted reversal.\n",
      "Dashed line indicates equal percentiles."
    )
  ) +
  theme_revision(11) +
  theme(
    legend.position = "none",
    plot.margin = margin(8, 35, 8, 8)
  )

rank_scatter_paths <- save_plot_pair(
  p_rank_scatter,
  "primary_vs_core_percentiles_v2",
  width = 7.4,
  height = 6.3
)


# -----------------------------------------------------------------------------
# Section 7. Export plotting data and a reproducible figure manifest
# -----------------------------------------------------------------------------

plot_data_paths <- c(
  heatmap = file.path(RESULT_DIR, "revision_plot_data_candidate_heatmap.csv"),
  priority_core = file.path(
    RESULT_DIR, "revision_plot_data_priority_core_trajectories.csv"
  ),
  priority_loo = file.path(
    RESULT_DIR, "revision_plot_data_priority_loo.csv"
  ),
  priority_null = file.path(
    RESULT_DIR, "revision_plot_data_priority_null.csv"
  ),
  rank_scatter = file.path(
    RESULT_DIR, "revision_plot_data_rank_scatter.csv"
  )
)

readr::write_csv(heatmap_data, plot_data_paths[["heatmap"]], na = "")
readr::write_csv(priority_core, plot_data_paths[["priority_core"]], na = "")
readr::write_csv(priority_loo, plot_data_paths[["priority_loo"]], na = "")
readr::write_csv(priority_null, plot_data_paths[["priority_null"]], na = "")
readr::write_csv(rank_scatter, plot_data_paths[["rank_scatter"]], na = "")

figure_paths <- c(
  heatmap_paths,
  trajectory_paths,
  loo_rank_paths,
  loo_ncs_paths,
  null_paths,
  rank_scatter_paths
)

figure_manifest <- data.frame(
  file = unname(figure_paths),
  format = tools::file_ext(unname(figure_paths)),
  size_bytes = as.numeric(file.info(unname(figure_paths))$size),
  md5 = unname(tools::md5sum(unname(figure_paths))),
  stringsAsFactors = FALSE
)

if (
  length(figure_paths) != 12L ||
    any(!file.exists(figure_paths)) ||
    any(figure_manifest$size_bytes <= 0) ||
    any(!file.exists(plot_data_paths))
) {
  stop("One or more diagnostic figure outputs failed validation.")
}

figure_manifest_path <- file.path(
  RESULT_DIR,
  "revision_candidate_robustness_figure_manifest.csv"
)
readr::write_csv(figure_manifest, figure_manifest_path)

result <- list(
  analysis_id = ANALYSIS_ID,
  script_build = SCRIPT_BUILD,
  manifest_content_sha256 = EXPECTED_LOCK,
  figure_paths = figure_paths,
  plot_data_paths = plot_data_paths,
  figure_manifest_path = figure_manifest_path,
  top20_perts = top20$pert,
  priority_perts = priority_perts,
  primary_observed_lines = observed_lines,
  input_provenance = data.frame(
    input = required_files,
    md5 = unname(tools::md5sum(required_files)),
    stringsAsFactors = FALSE
  )
)

saveRDS(result, OUTPUT_RDS, compress = TRUE)

result_check <- readRDS(OUTPUT_RDS)
if (
  !identical(result_check$manifest_content_sha256, EXPECTED_LOCK) ||
    length(result_check$figure_paths) != 12L ||
    any(!file.exists(result_check$figure_paths))
) {
  stop("Post-write visualization result validation failed.")
}

